local function validpoint(r)
 return type(r)=="table" and type(r.mapID)=="number" and r.mapID>=1 and
 type(r.x)=="number" and r.x>=0 and r.x<=1 and
 type(r.y)=="number" and r.y>=0 and r.y<=1
end
function M:GetWaypoint(category,id)
 if type(id)~="string" or #id>24 then return nil,"INVALID_OWNER_RECORD_ID" end
 if category=="TRAINER" and id=="TR026" then return nil,"ANNORA_ENTRANCE_IS_NOT_NPC_POSITION" end
 local r=records[tostring(category)..":"..id]
 -- Reuse the existing material source catalogue; one canonical geography owner.
 if not r and category=="VENDOR" then
  local root=JLP.data and JLP.data.materialAcquisitionSources
  for _,v in ipairs(root and root.vendors or {})do if v.id==id then
   r={id=v.id,npcID=v.npcID,name=v.name,zone=v.zone,faction=v.faction,
    mapID=v.mapID,x=v.x,y=v.y,sourceSHA=v.fieldSHA256,sourceRow=v.url,
    ownerAuthority=v.geographyOrigin or "FOREVER_EXTERNAL_GEOGRAPHIC_REFERENCE"};break end end
 end
 if not r and category=="RECIPE_SOURCE" then
  local data=JLP.data and JLP.data.leatherworking
  local root=data and data.progression
  for recipeID,f in pairs(root and root.recipes or {})do
   local d=f.dropResearch;local g=d and data.recipeSourceGeography and data.recipeSourceGeography[recipeID]
   if g and g.id==id and g.recipeID==recipeID and g.npcID==d.npcID and g.itemID==f.recipeItemID then
    r={id=g.id,npcID=g.npcID,name=g.name,zone=g.zone,faction=g.faction,profession="LEATHERWORKING",
     mapID=g.mapID,x=g.x,y=g.y,sourceSHA=g.fieldSHA256,sourceRow=g.url,
     ownerAuthority="FOREVER_EXTERNAL_REPORTED_DROP_GEOGRAPHY"};break
   end
  end
 end
 if not r then return nil,"NO_CANONICAL_OWNER_RECORD" end
 if not validpoint(r) then return nil,"OWNER_MAP_ID_UNRESOLVED" end
 return {serviceID=r.id,kind=category=="TRAINER" and "trainer" or
   (category=="BANK" and "bank" or category=="CRAFT_STATION"and "craft_station"or category=="VENDOR" and "vendor" or category=="RECIPE_SOURCE"and "drop"or "auction_house"),name=r.name,
   npcID=r.npcID,stationID=r.stationID,objectID=r.objectID,stationFocus=r.stationFocus,trainerServiceID=r.trainerServiceID,profession=r.profession,rank=r.rank,zone=r.zone,faction=r.faction or "Horde",
   hordeAccess=true,ownerDataAuthorized=true,ownerAuthority=r.ownerAuthority,
   sourceSHA=r.sourceSHA,sourceRow=r.sourceRow,sourceQualified=true,
   state="SOURCE_QUALIFIED",productionAuthorized=false,nativeDispatchAllowed=false,
   nav={mapID=r.mapID,x=r.x,y=r.y,mapDomain="UI_MAP_ID",
      evidence=(r.ownerAuthority=="USER_PROJECT_POSITION_2026_10_26_REV2"and "USER_PROJECT_GEO:"or r.ownerAuthority=="FOREVER_EXTERNAL_TRAINER_GEOGRAPHY"and "FOREVER_EXTERNAL_TRAINER_GEO:"or r.trainerServiceID and "USER_ANVIL_TRAINER_ALIAS:"or category=="CRAFT_STATION"and "FOREVER_EXTERNAL_FORGE_GEO:"or category=="RECIPE_SOURCE"and "FOREVER_EXTERNAL_REPORTED_SPAWN_GEO:"or category=="VENDOR" and "FOREVER_EXTERNAL_GEO:" or "JLP_OWNER_NAV_2026_10_17:")..r.id,sourceQualified=true}},"OWNER_CANONICAL"
end
-- The original owner record qualifies only an OUTDOOR approach. Never expose
-- these Badlands coordinates as Annora's internal location or an instance edge.

-- Exact externally documented quest-giver position, not a dungeon objective.
function M:GetMagnusQuestWaypoint(recipeID,access)
 local d=JLP.data and JLP.data.blacksmithing and JLP.data.blacksmithing.magnusAccess
 if not d or (recipeID~=10013 and recipeID~=16971)or not access or
  (access.status~="QUEST_START"and access.status~="QUEST_RETURN")then return nil end
 local q=d.questGiver
 if not q or q.npcID~=11216 or q.mapID~=1422 or q.x~=.70 or q.y~=.73 then return nil end
 return {serviceID="MAGNUS_EVA",kind="quest_giver",npcID=q.npcID,name=q.name,
  profession="BLACKSMITHING",recipeID=recipeID,accessNPCID=11278,accessItemID=d.itemID,
  accessQuestID=access.questID,accessStage=access.status,zone=q.zone,faction=q.faction,
  ownerDataAuthorized=true,ownerAuthority="FOREVER_BETA_GUIDE_QUEST_GEOGRAPHY",
  sourceRow=d.guideURL,sourceQualified=true,state="SOURCE_QUALIFIED",hordeAccess=true,
  nativeDispatchAllowed=false,productionAuthorized=false,
  nav={mapID=q.mapID,x=q.x,y=q.y,mapDomain="UI_MAP_ID",evidence="FOREVER_GUIDE_EVA_OUTDOOR_QUEST_START_RETURN",sourceQualified=true}}
end

function M:GetAnnoraApproach()
 local r=records["TRAINER:TR026"]
 if not r or not validpoint(r) then return nil end
 return {serviceID="ULDAMAN_REAR",kind="dungeon_entrance",name="Uldaman rear entrance (Annora approach)",
  profession="ENCHANTING",zone="Badlands",faction="Neutral",goalNPCID=11073,
  approachOnly=true,pointRole="OUTDOOR_REAR_ENTRANCE_NOT_NPC",hordeAccess=true,
  ownerDataAuthorized=true,ownerAuthority=r.ownerAuthority,sourceSHA=r.sourceSHA,sourceRow=r.sourceRow,
  sourceQualified=true,state="SOURCE_QUALIFIED",productionAuthorized=false,nativeDispatchAllowed=false,
  nav={mapID=r.mapID,x=r.x,y=r.y,mapDomain="UI_MAP_ID",sourceQualified=true,
   evidence="OWNER_TR026_OUTDOOR_APPROACH_ONLY"}}
end

-- Reference qualification and current geometry are independent. C_Map names,
-- AreaTable/instance IDs and a saved waypoint can never create the binding.
local function annoraCall(name,...)
 if type(C_Map)~="table" or type(C_Map[name])~="function" then return nil end
 local ok,a,b=pcall(C_Map[name],...);if ok then return a,b end
end
local function annoraFinite(n) return type(n)=="number" and n==n and n~=math.huge and n~=-math.huge end
local function annoraID(n) return annoraFinite(n) and n>0 and n==math.floor(n) end
function M:GetAnnoraInternal()
 local d=JLP.data and JLP.data.enchanting and JLP.data.enchanting.annoraAccess
 local r=d and d.positionReference;local b=d and d.referenceMapBinding
 if not r or r.referenceID~="ANNORA_USER_20261026" or r.npcID~=11073 or
  r.x~=.558 or r.y~=.608 or r.xPercent~=55.8 or r.yPercent~=60.8 or d.instanceMapID~=70 then
  return nil,"ANNORA_REFERENCE_CONFLICT" end
 if not b or b.status~="QUALIFIED_REFERENCE_PROJECTION" then return nil,"ANNORA_REFERENCE_UI_MAP_ART_PROJECTION_UNBOUND" end
 if b.referenceID~=r.referenceID or b.npcID~=11073 or b.instanceMapID~=70 or
  b.mapDomain~="UI_MAP_ID" or b.coordinateSpace~="NORMALIZED_UI_MAP" or
  b.sameCoordinates~=true or type(b.projectionEvidence)~="string" or #b.projectionEvidence<12 or
  not annoraID(b.uiMapID) or not annoraID(b.uiMapArtID) or
  b.uiMapID==70 or b.uiMapID==1337 or b.uiMapID==1517 then
  return nil,"ANNORA_REFERENCE_BINDING_INCOMPLETE_OR_CONFLICT" end
 if type(GetInstanceInfo)~="function" then return nil,"ANNORA_INSTANCE_API_UNAVAILABLE" end
 local ok,_,kind,_,_,_,_,_,id=pcall(GetInstanceInfo)
 if not ok or kind~="party" or id~=70 then return nil,"ANNORA_INSTANCE_MISMATCH" end
 local info=annoraCall("GetMapInfo",b.uiMapID)
 if type(info)~="table" or info.mapID~=b.uiMapID then return nil,"ANNORA_UI_MAP_INFO_UNVERIFIED" end
 if annoraCall("GetBestMapForUnit","player")~=b.uiMapID then return nil,"ANNORA_PLAYER_REFERENCE_MAP_MISMATCH" end
 if annoraCall("GetMapArtID",b.uiMapID)~=b.uiMapArtID then return nil,"ANNORA_REFERENCE_ART_MISMATCH" end
 local group=annoraCall("GetMapGroupID",b.uiMapID)
 if not annoraFinite(group) or group<0 or group~=math.floor(group) or group~=b.mapGroupID then
  return nil,"ANNORA_MAP_GROUP_UNVERIFIED" end
 if group>0 then
  local members=annoraCall("GetMapGroupMembersInfo",group)
  if type(members)~="table" or #members==0 then return nil,"ANNORA_FLOOR_MEMBERS_UNKNOWN" end
  local matched,count=nil,0
  for _,row in ipairs(members)do
   if type(row)~="table" or not annoraID(row.mapID) or not annoraFinite(row.relativeHeightIndex) then return nil,"ANNORA_FLOOR_MEMBERS_INVALID" end
   if row.mapID==b.uiMapID then matched=row.relativeHeightIndex;count=count+1 end
  end
  if count~=1 or (#members>1 and b.relativeHeightIndex==nil) or
   b.relativeHeightIndex~=nil and matched~=b.relativeHeightIndex then return nil,"ANNORA_FLOOR_MISMATCH_OR_UNBOUND" end
 end
 local pos=annoraCall("GetPlayerMapPosition",b.uiMapID,"player")
 local good,x,y=pcall(function()return pos:GetXY()end)
 if not good or not annoraFinite(x) or not annoraFinite(y) or x<0 or x>1 or y<0 or y>1 then return nil,"ANNORA_PLAYER_POSITION_UNAVAILABLE" end
 local target={mapID=b.uiMapID,x=r.x,y=r.y,mapDomain="UI_MAP_ID"}
 local metric=false
 if type(C_Map.GetWorldPosFromMapPos)=="function" and type(CreateVector2D)=="function" then
  local wa,pa=annoraCall("GetWorldPosFromMapPos",b.uiMapID,CreateVector2D(x,y))
  local wb,pb=annoraCall("GetWorldPosFromMapPos",b.uiMapID,CreateVector2D(r.x,r.y))
  if wa~=nil or wb~=nil then
   if wa~=70 or wb~=70 then return nil,"ANNORA_WORLD_INSTANCE_MISMATCH" end
   local a,ax,ay=pcall(function()return pa:GetXY()end)
   local c,bx,by=pcall(function()return pb:GetXY()end)
   if not a or not c or not annoraFinite(ax) or not annoraFinite(ay) or not annoraFinite(bx) or not annoraFinite(by) then return nil,"ANNORA_WORLD_GEOMETRY_UNVERIFIED" end
   metric=true
  end
 end
 if not metric then
  local w,h=annoraCall("GetMapWorldSize",b.uiMapID)
  if not annoraFinite(w) or not annoraFinite(h) or w<=0 or h<=0 then return nil,"ANNORA_BEARING_GEOMETRY_UNVERIFIED" end
 end
 target.evidence="ANNORA_BOUND_REFERENCE_DIRECT_BEARING"
 target.sourceQualified=true
 return {serviceID="ULDAMAN_ANNORA",kind="dungeon_npc",name="Annora (direct bearing, not corridor route)",
  profession="ENCHANTING",zone="Uldaman",faction="Neutral",npcID=11073,goalNPCID=11073,
  approachOnly=false,pointRole="INTERNAL_NPC_DIRECT_BEARING",directBearing=true,
  referenceID=r.referenceID,bindingEvidence=b.projectionEvidence,bindingArtID=b.uiMapArtID,
  bindingGroupID=group,bindingFloor=b.relativeHeightIndex,metricGeometry=metric,
  hordeAccess=true,ownerDataAuthorized=true,sourceQualified=true,state="SOURCE_QUALIFIED",
  nativeDispatchAllowed=false,productionAuthorized=false,nav=target},"ANNORA_REFERENCE_AND_CURRENT_GEOMETRY_QUALIFIED"
end

function M:GetTrainerForRank(profession,rank)
 if type(profession)~="string" or type(rank)~="string" then return nil end
 rank=rank:upper():match("^(%S+)")
 for _,r in ipairs(trainers) do
   if r.profession==profession and r.rank==rank and validpoint(r) then
     return self:GetWaypoint("TRAINER",r.id)
   end
 end
 return nil,"NO_QUALIFIED_TRAINER"
end
function M:GetTrainerByName(profession,rank,name)
 if type(profession)~="string" or type(rank)~="string" or
    type(name)~="string" then return nil end
 local tier=rank:upper():match("^(%S+)")
 for _,row in ipairs(trainers) do
   if row.profession==profession and row.rank==tier and row.name==name then
      return self:GetWaypoint("TRAINER",row.id)
   end
 end
 return nil,"OWNER_TRAINER_NOT_FOUND"
end
function M:GetServiceList(category)
 if category~="BANK" and category~="AUCTION_HOUSE" and category~="TRAINER"and category~="CRAFT_STATION"then return {}end
 local result={};local source=category=="TRAINER"and trainers or category=="CRAFT_STATION"and forges or services
 for _,row in ipairs(source) do
   if (category=="TRAINER"or category=="CRAFT_STATION"or row.category==category)then
     local item=self:GetWaypoint(category,row.id)
     result[#result+1]=item or {serviceID=row.id,name=row.name,zone=row.zone,state="UNKNOWN",sourceQualified=false}
   end
 end
 if category=="CRAFT_STATION"then for _,row in ipairs(anvils)do result[#result+1]=self:GetWaypoint(category,row.id)end end
 if category=="TRAINER"then for _,row in ipairs(herbTrainerReferences)do result[#result+1]=self:GetWaypoint(category,row.id)end end
 return result
end
-- A typed, detached identity inventory; no runtime caller may invent aliases.
function M:GetTaxiNodeIdentities() return duplicate(taxiIdentity) end
function M:GetTransportPlaces() return duplicate(transportPlaces) end
-- Read-only canonical connection inventory; returns detached copies, no graph admission.
function M:GetTransportSourceRoutes() return duplicate(transport) end
function M:GetComputedRoadmap(fromST,toST)
 if type(fromST)~="string" or type(toST)~="string" then return nil end
 local byID={} for _,p in ipairs(transportPlaces) do if p.category=="Flight Path" then byID[p.id]=p end end
 if not byID[fromST] or not byID[toST] then return nil end
 if fromST==toST then return {fromST=fromST,toST=toST,stages=0,directFlight=true,via="Ingen",routeIds={}} end
 local adjacency={}
 for _,e in ipairs(transport) do if e.mode=="FLIGHT" then
   local a=e.fromST;adjacency[a]=adjacency[a] or {};adjacency[a][#adjacency[a]+1]=e
 end end
 local q={fromST};local i=1;local seen={[fromST]=true};local parent={}
 while q[i] and not seen[toST] do
  local at=q[i];i=i+1
  for _,e in ipairs(adjacency[at] or {}) do
   if not seen[e.toST] then seen[e.toST]=true;parent[e.toST]={from=at,id=e.id};q[#q+1]=e.toST end
  end
 end
 if not seen[toST] then return nil,"NO_ROUTE_IN_EXCEL" end
 local ids,vias={},{};local at=toST
 while at~=fromST do
  local step=parent[at];if not step then return nil,"BROKEN_PATH" end
  table.insert(ids,1,step.id)
  if step.from~=fromST then table.insert(vias,1,byID[step.from].flightPoint) end
  at=step.from
 end
 return {fromST=fromST,toST=toST,fromName=byID[fromST].flightPoint,toName=byID[toST].flightPoint,
     directFlight=#ids==1,stages=#ids,via=#vias>0 and table.concat(vias," -> ") or "Ingen",
     routeIds=ids,ownerAuthority="COMPUTED_FROM_EXCEL_DIRECT_CONNECTIONS"}
end
function M:GetInventory()
 local out={transportRows=#transport,transportPlaces=#transportPlaces,
    computedRoadmapRows=#roadmaps,bankRows=0,auctionRows=0,trainerRows=#trainers,externalTrainerRows=#herbTrainerReferences,trainerReferenceRows=#trainers+#herbTrainerReferences,
    mappedServiceRows=0,mappedTrainerRows=0,topologyNodes=#nodes,
    mappedTransportRows=0,missingTransportRows=0,ownerAuthority="OWNER_PRODUCTION_AUTHORIZED",
    nativeClientTest="NOT_RUN",flightUnlockObservation="UNKNOWN_UNTIL_TAXI_CLIENT_OBSERVATION",recipeQualifiedIncrement=0}
 for _,r in ipairs(services) do
   if r.category=="BANK" then out.bankRows=out.bankRows+1 else out.auctionRows=out.auctionRows+1 end
   if validpoint(r) then out.mappedServiceRows=out.mappedServiceRows+1 end
 end
 -- Legacy mappedTrainerRows counts raw geographic references, including the
 -- entrance row. It is not a count of qualified NPC positions.
 for _,r in ipairs(trainers) do if validpoint(r) then out.mappedTrainerRows=out.mappedTrainerRows+1 end end
 out.dungeonApproachRows=self:GetAnnoraApproach() and 1 or 0
 out.qualifiedTrainerPositionRows=out.mappedTrainerRows-out.dungeonApproachRows
 local verified=self:GetTransportDataset()
 out.mappedTransportRows=#verified.edges
 out.missingTransportRows=#transport-#verified.edges
 out.canonicalExcelSourceSHA='7db7b31ef0fe6352bfaf1729b88315bd0552722feada527496a87617ace890cf'
 out.canonicalExcelFlightPoints=35;out.canonicalExcelRouteRows=162
 out.unmappedRowsAreNotAuthorized=true
 return out
end
-- Internal immutable identity comparison. RegisterVerifiedDataset must not trust
-- arbitrary caller-supplied rows or a self-attested SHA/approval marker.
local function deepEqual(a,b,depth)
 if depth>7 or type(a)~=type(b) then return false end
 if type(a)~="table" then return a==b end
 for k,v in pairs(a) do if not deepEqual(v,b[k],depth+1) then return false end end
 for k in pairs(b) do if a[k]==nil then return false end end
 return true
end
local function equalSource(dataset)
 -- Compare against an independent private canonical representation, not against
 -- self-reported hashes/status. Recursion also rejects off-page holes and extras.
 if type(dataset)~="table" then return false end
 return deepEqual(dataset,M:GetTransportDataset(),0)
end
function M:MatchesCanonicalTransport(dataset) return equalSource(dataset) end
function M:MatchesCanonicalTaxiIdentities(dataset) return deepEqual(dataset,taxiIdentity,0) end
local nodeByST={}
for _,n in ipairs(nodes) do nodeByST[n.stId]=n end
local function byExcelNode(stID) return nodeByST[stID] end
-- These IDs are the source's UI-map identities, not translated display text.
-- Classic continent relations provide an independent structural check. The
-- additional Forever map IDs use the source's explicit numeric identity contract;
-- their unobserved continent relationship is deliberately not guessed.
local continentByMap={
 [1434]=1415,[1428]=1415,[1417]=1415,[1418]=1415,[1423]=1415,[1425]=1415,
 [1435]=1415,[1424]=1415,[1421]=1415,[1427]=1415,[1420]=1415,
 [1448]=1414,[1445]=1414,[1444]=1414,[1413]=1414,[1451]=1414,[1452]=1414,
 [1441]=1414,[1446]=1414,[1449]=1414,[1450]=1414,[1454]=1414,[1443]=1414,
 [1440]=1414,[1442]=1414,[1456]=1414,[1447]=1414,[1411]=1414,[1412]=1414}
local locales={enUS=true,enGB=true,deDE=true,esES=true,esMX=true,frFR=true,
 itIT=true,koKR=true,ptBR=true,ruRU=true,zhCN=true,zhTW=true}
local function matchMap(row,locale)
 if type(row.mapID)~="number" or type(C_Map)~="table" or
    type(C_Map.GetMapInfo)~="function" then return false end
 local ok,info=pcall(C_Map.GetMapInfo,row.mapID)
 if not ok or type(info)~="table" or info.mapID~=row.mapID or info.mapType~=3 or
    type(info.name)~="string" or info.name=="" then return false end
 local parent=continentByMap[row.mapID]
 if parent and info.parentMapID~=nil and info.parentMapID~=parent then return false end
 local function norm(v) return tostring(v):lower():gsub("^the ",""):gsub("%s+"," ") end
 if locale=="enUS" or locale=="enGB" then return norm(info.name)==norm(row.zone) end
 -- Localized names are presentation only for the explicit UI-map identity.
 -- Missing/foreign IDs, non-zone maps, wrong structures, unsupported locales
 -- and unsupported locales never acquire transport authority. Client builds
 -- are provenance; a later client with the same native map capabilities and
 -- identities is not disabled merely because its build number changed.
 return locales[locale]==true
end
function M:GetTransportDataset()
 local d={contract="juzt-travel-dataset-v1",nodes={},edges={}}
 local valid={}
 local locale,build
 if type(GetLocale)=="function" then local ok,value=pcall(GetLocale);if ok then locale=value end end
 local reader=JLP:GetModule("ClientBuildInfo")
 if reader and type(reader.GetBuildNumber)=="function" then build=reader:GetBuildNumber()
 elseif type(GetBuildInfo)=="function" then
  local ok,version,value=pcall(GetBuildInfo);if ok then build=tonumber(value) end
 end
 for _,r in ipairs(nodes) do
  if matchMap(r,locale) then
   valid[r.id]=true
   d.nodes[#d.nodes+1]={id=r.id,label=r.label,placeName=r.name,zone=r.zone,mapID=r.mapID,x=r.x,y=r.y,
      kind="TRANSPORT_STOP",confirmed=true,clientVerified=false,ownerAuthorized=true,
      provenance="USER_EXCEL_70450_QUALIFIED_UI_MAP_IDENTITY",sourceBuild=70450,observedClientBuild=build}
  end
 end
 for _,r in ipairs(transport) do
  local from,to=byExcelNode(r.fromST),byExcelNode(r.toST)
   if valid[r.fromID] and valid[r.toID] then
   d.edges[#d.edges+1]={id=r.id,from=r.fromID,to=r.toID,mode=r.mode,
     faction=r.faction,costUnits=r.costUnits,requiresUnlock=r.requiresUnlock,
     mustConfirm=true,status="verified",clientVerified=false,ownerAuthorized=true,
     requiresClass=((from and from.access=="Kun Druid") or
       (to and to.access=="Kun Druid")) and "DRUID" or nil,
     provenance="USER_EXCEL_70450:"..r.id}
  end
 end
 return d
end

JLP:RegisterModule("OwnerAuthorizedNavigation",M)
